```js
export function debounce(fn, wait) {
  let t;
  return function (...args) {
    clearTimeout(t);
    t = setTimeout(() => fn.apply(this, args), wait);
  };
}
```

Each call resets the timer; only the last burst runs.

```python
def flatten(nested):
    out = []
    for item in nested:
        if isinstance(item, list):
            out.extend(flatten(item))
        else:
            out.append(item)
    return out
```
Each nested list is flattened recursively; non-list items are appended as-is.

```js
function chunk(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) {
    out.push(arr.slice(i, i + size));
  }
  return out;
}
```
`slice` safely returns fewer than `size` items for the final chunk.

```python
def has_cycle(graph):
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {n: WHITE for n in graph}
    for nbrs in graph.values():
        for n in nbrs:
            color.setdefault(n, WHITE)

    def dfs(n):
        color[n] = GRAY
        for m in graph.get(n, []):
            if color[m] == GRAY:
                return True
            if color[m] == WHITE and dfs(m):
                return True
        color[n] = BLACK
        return False

    return any(dfs(n) for n, c in color.items() if c == WHITE)
```

Gray back-edge means a cycle.
